import{_ as a,c as n,d as l,Z as e}from"./chunks/framework.B0uuYL3Y.js";const p="/microarch/page-table-isolation.png",b=JSON.parse('{"title":"进入内核时怎样切换页表","description":"沿一次 Linux x86-64 系统调用追踪两个页表根、共用的入口页，以及返回用户态时的 TLB 处理。","frontmatter":{"title":"进入内核时怎样切换页表","description":"沿一次 Linux x86-64 系统调用追踪两个页表根、共用的入口页，以及返回用户态时的 TLB 处理。","date":"2026-11-26","tags":["微架构安全","页表隔离","Linux","CR3","PCID"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-04f-page-table-isolation.md","filePath":"posts/microarch-04f-page-table-isolation.md"}'),o={name:"posts/microarch-04f-page-table-isolation.md"};function t(r,s,c,i,y,d){return n(),l("div",null,s[0]||(s[0]=[e('<p>用户程序用 <code>read()</code> 从文件读取数据，系统调用指令把执行交给内核。若用户态的页表只保留了少量内核映射，处理器要从哪里取到入口代码？内核开始处理之后，为什么还能向同一个进程的用户缓冲区复制数据？</p><p>这两个问题可以沿一次页表切换一起回答。本文以开启页表隔离的 Linux v6.12 x86-64 正常系统调用为例。先修是<a href="./microarch-02a-translation.html#sv39-permissions">页表翻译与访问权限</a>。那一节用 RISC-V 说明通用过程，这一节的寄存器、指令和入口规则采用 x86。</p><nav class="table-of-contents"><ul><li><a href="#pti-roots">两个页表根分别保留哪些映射</a></li><li><a href="#pti-entry">一次系统调用里，权限级和 CR3 怎样改变</a></li><li><a href="#pti-model">用一个页表模型核对入口和出口</a></li><li><a href="#pti-tlb">切了页表，旧的翻译怎样处理</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="pti-roots" tabindex="-1">两个页表根分别保留哪些映射 <a class="header-anchor" href="#pti-roots" aria-label="Permalink to &quot;两个页表根分别保留哪些映射 {#pti-roots}&quot;">​</a></h2><p>传统设计可以让同一份顶级页表同时包含用户地址和内核地址。内核页通过页表权限限制为特权态可用。<a href="./microarch-04e-meltdown.html#meltdown-pti">Meltdown 一节</a>讨论的经典情况中，目标页已有有效翻译，架构上的读取仍因权限检查被拒绝。页表隔离（Page Table Isolation，PTI）进一步缩小在用户运行期间参与翻译的内核地址范围。</p><p>图 1 左边展示一套映射。右边并排展示启用 PTI 后的两套视图。中间的内核视图保留完整内核映射及该进程的用户地址。最右边的用户视图保留该进程的用户地址，以及少量进入、退出内核所需的映射。图中带颜色的区域表示页表所覆盖的<strong>虚拟地址范围</strong>，不代表分配了两份用户数据。</p><figure class="lesson-figure" style="max-width:620px;"><a href="/microarch/page-table-isolation.png" aria-label="放大查看页表隔离原图"><img src="'+p+`" alt="页表隔离前使用同一套用户及内核映射，隔离后内核视图保留全部范围，用户视图仅保留用户区与少量内核入口映射" width="620" height="517" style="filter:grayscale(1);background-color:white;" loading="lazy" decoding="async"></a><figcaption>图 1　页表隔离前后的映射范围。最右边缩小的是用户视图中的内核映射范围。点击可查看原图。</figcaption></figure><p>将图中的区域缩小成三个示意页。U 是当前进程的普通用户页，E 是内核入口用的代码页，K 是一个普通的内核数据页。</p><table tabindex="0"><thead><tr><th>虚拟页</th><th>用户视图</th><th>内核视图</th></tr></thead><tbody><tr><td>U，用户页</td><td>有映射，按用户页自己的权限访问</td><td>有同一份数据的映射。Linux PTI 把此视图的用户部分限制为不可执行</td></tr><tr><td>E，系统调用入口</td><td>有映射，只供特权态使用</td><td>有映射，只供特权态使用</td></tr><tr><td>K，普通内核数据</td><td>无映射</td><td>有映射，只供特权态使用</td></tr></tbody></table><p>这是权限和存在性两个条件。系统在用户模式时，E 有翻译却受特权级限制，K 在当前视图根本没有翻译。访问 E 与访问 K 都会被拒绝，页错误原因却不同。真实内核的少量公共映射还涉及进入和离开时需要的每 CPU 结构，表中用 E 代表入口代码。</p><p>Linux 为一个用户地址空间维护顶级页目录（PGD）的两份根。用户部分的顶级项可分别指向同一组下级表，页表项和对应物理页由两份视图共用。这样改动一个普通用户页时，下级页表项无需双份维护。内核还会在新增用户顶级项时同步另一份根。内核视图保留用户数据映射，是因为诸如 <code>copy_to_user()</code> 的内核操作需要在合适的权限控制下访问这些数据。</p><h2 id="pti-entry" tabindex="-1">一次系统调用里，权限级和 CR3 怎样改变 <a class="header-anchor" href="#pti-entry" aria-label="Permalink to &quot;一次系统调用里，权限级和 CR3 怎样改变 {#pti-entry}&quot;">​</a></h2><p>x86-64 的 <code>CR3</code> 指定当前页表根。在支持且启用 PCID 时，<code>CR3</code> 还携带当前翻译上下文的标识。一次普通的 64 位 <code>SYSCALL</code> 将控制流转到内核入口并改变当前特权级，但页表根仍然是调用前使用的那份。<code>SYSCALL</code> 也不会把栈指针自动换成普通内核栈。入口代码必须在这个短暂的组合下工作，即特权态已经开始使用、用户视图仍然有效。</p><p>以下沿 Linux v6.12 的 <code>entry_SYSCALL_64</code> 和可使用 <code>SYSRETQ</code> 的返回路径走一遍。慢速返回和中断入口各有其他处理，下面只取这条路径。</p><table tabindex="0"><thead><tr><th>时刻</th><th>当前权限级</th><th>当前页表视图</th><th>这一步发生什么</th></tr></thead><tbody><tr><td>调用前</td><td>用户态</td><td>用户</td><td>用户代码执行 <code>SYSCALL</code></td></tr><tr><td>刚进入入口</td><td>内核态</td><td>用户</td><td>入口代码可取指，暂存原用户栈指针</td></tr><tr><td>入口代码切换 <code>CR3</code></td><td>内核态</td><td>内核</td><td>得到完整内核映射，切到普通内核栈，运行内核处理</td></tr><tr><td>开始返回</td><td>内核态</td><td>内核</td><td>把最后所需的状态迁到入口和出口都能使用的栈</td></tr><tr><td>出口代码切换 <code>CR3</code></td><td>内核态</td><td>用户</td><td>从公共出口区域完成返回前操作</td></tr><tr><td><code>SYSRETQ</code> 返回后</td><td>用户态</td><td>用户</td><td>回到用户指令流</td></tr></tbody></table><p>入口先把用户栈指针保存到每 CPU 任务状态段（TSS）的临时字段，再调用 <code>SWITCH_TO_KERNEL_CR3</code>，随后才从内核的每 CPU 状态取普通内核栈指针。返回时，代码先切到过渡栈，再使用 <code>SWITCH_TO_USER_CR3_STACK</code>。这个先后顺序解释了为什么用户页表中要有少量内核入口页和每 CPU 入口结构。页表根已经切回用户视图时，出口代码和剩下要使用的数据仍需要可寻址。</p><h2 id="pti-model" tabindex="-1">用一个页表模型核对入口和出口 <a class="header-anchor" href="#pti-model" aria-label="Permalink to &quot;用一个页表模型核对入口和出口 {#pti-model}&quot;">​</a></h2><p>下列 Python 3 模型只判断三份示意页能否找到映射、能否满足本次读取或取指。<code>Entry</code> 的三个字段保存页号、用户可访问位和本次视图的有效执行权限。真实 x86 的权限由页表路径和处理器配置共同决定，这里只保留本例用到的结果。</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">from</span><span style="color:#839496;"> typing </span><span style="color:#859900;">import</span><span style="color:#839496;"> NamedTuple</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">class</span><span style="color:#CB4B16;"> Entry</span><span style="color:#839496;">(</span><span style="color:#6C71C4;">NamedTuple</span><span style="color:#839496;">):</span></span>
<span class="line"><span style="color:#839496;">    frame: </span><span style="color:#859900;">str</span></span>
<span class="line"><span style="color:#839496;">    user_allowed: </span><span style="color:#859900;">bool</span></span>
<span class="line"><span style="color:#839496;">    executable: </span><span style="color:#859900;">bool</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">user_root </span><span style="color:#859900;">=</span><span style="color:#839496;"> {</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;U&quot;</span><span style="color:#839496;">: Entry(</span><span style="color:#2AA198;">&quot;frame-u&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">True</span><span style="color:#839496;">, </span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;E&quot;</span><span style="color:#839496;">: Entry(</span><span style="color:#2AA198;">&quot;frame-entry&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">, </span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">}</span></span>
<span class="line"><span style="color:#839496;">kernel_root </span><span style="color:#859900;">=</span><span style="color:#839496;"> {</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;U&quot;</span><span style="color:#839496;">: Entry(</span><span style="color:#2AA198;">&quot;frame-u&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">True</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;E&quot;</span><span style="color:#839496;">: user_root[</span><span style="color:#2AA198;">&quot;E&quot;</span><span style="color:#839496;">],</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;K&quot;</span><span style="color:#839496;">: Entry(</span><span style="color:#2AA198;">&quot;frame-k&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">, </span><span style="color:#B58900;">False</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">}</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">def</span><span style="color:#268BD2;"> access</span><span style="color:#839496;">(root, page, </span><span style="color:#859900;">*</span><span style="color:#839496;">, user_mode, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">):</span></span>
<span class="line"><span style="color:#839496;">    entry </span><span style="color:#859900;">=</span><span style="color:#839496;"> root.get(page)</span></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#839496;"> entry </span><span style="color:#859900;">is</span><span style="color:#B58900;"> None</span><span style="color:#839496;">:</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#2AA198;"> &quot;unmapped&quot;</span></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#839496;"> user_mode </span><span style="color:#859900;">and</span><span style="color:#859900;"> not</span><span style="color:#839496;"> entry.user_allowed:</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#2AA198;"> &quot;permission&quot;</span></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#839496;"> execute </span><span style="color:#859900;">and</span><span style="color:#859900;"> not</span><span style="color:#839496;"> entry.executable:</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#2AA198;"> &quot;permission&quot;</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#839496;"> entry.frame</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">results </span><span style="color:#859900;">=</span><span style="color:#839496;"> [</span></span>
<span class="line"><span style="color:#839496;">    access(user_root, </span><span style="color:#2AA198;">&quot;U&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    access(user_root, </span><span style="color:#2AA198;">&quot;E&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    access(user_root, </span><span style="color:#2AA198;">&quot;E&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    access(user_root, </span><span style="color:#2AA198;">&quot;K&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    access(kernel_root, </span><span style="color:#2AA198;">&quot;K&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    access(user_root, </span><span style="color:#2AA198;">&quot;E&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">False</span><span style="color:#839496;">, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">    access(user_root, </span><span style="color:#2AA198;">&quot;U&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">),</span></span>
<span class="line"><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> results </span><span style="color:#859900;">==</span><span style="color:#839496;"> [</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;frame-u&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;permission&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;frame-entry&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;unmapped&quot;</span><span style="color:#839496;">,</span></span>
<span class="line"><span style="color:#2AA198;">    &quot;frame-k&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;frame-entry&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;frame-u&quot;</span><span style="color:#839496;">,</span></span>
<span class="line"><span style="color:#839496;">]</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> access(kernel_root, </span><span style="color:#2AA198;">&quot;U&quot;</span><span style="color:#839496;">, user_mode</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">, execute</span><span style="color:#859900;">=</span><span style="color:#B58900;">True</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#2AA198;"> &quot;permission&quot;</span></span>
<span class="line"><span style="color:#268BD2;">print</span><span style="color:#839496;">(results)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br></div></div><p>第三项模拟刚进入内核，权限级已允许访问 E，此时页表根仍是用户视图。第四项用相同权限级查询 K，仍因缺少映射而无法取得页号。第五项切换到内核视图以后，K 才有翻译。最后的断言说明另一种异常路径。如果返回用户态时错误地留下内核视图，虽然 U 的物理页相同，取指仍会遇到不可执行限制。</p><h2 id="pti-tlb" tabindex="-1">切了页表，旧的翻译怎样处理 <a class="header-anchor" href="#pti-tlb" aria-label="Permalink to &quot;切了页表，旧的翻译怎样处理 {#pti-tlb}&quot;">​</a></h2><p>页表是翻译的依据，TLB 则缓存翻译结果。若每次进出系统调用都丢掉许多已有翻译，返回以后要额外做页表遍历。支持 PCID 的系统可以给用户视图和内核视图不同的翻译标识。这样一次切换选择相应的记录，已有记录在满足条件时还能保留。两个视图里的 U 最终指向同一物理页，也仍然可以有不同的权限属性和 TLB 上下文。</p><table tabindex="0"><thead><tr><th>条件</th><th>Linux v6.12 的这条返回路径怎样处理</th></tr></thead><tbody><tr><td>支持 PCID，用户视图对应的翻译仍有效</td><td>切到用户页表根与对应的 PCID。可以使用不失效已有翻译的写入方式</td></tr><tr><td>支持 PCID，内核记录用户 PCID 需要失效</td><td>返回时先处理这个标记，切换时使相关旧翻译失效</td></tr><tr><td>未使用 PCID</td><td>沿普通页表根切换路径，非全局翻译不能像带标识的有效记录那样保留</td></tr></tbody></table><p>这里的关键在于“仍有效”的条件。更新页表后，原先缓存的翻译必须按相应范围失效。Linux 会给用户 PCID 记录待处理状态，并在真正切回用户页表时检查。对于仅在内核视图有映射的内核页，PTI 也限制使用可跨上下文保留的全局页属性。这样切换时查到的翻译与当前视图的映射范围保持一致。</p><p>保护作用可以回到 K 这一个页来检查。启用 PTI 后，正常用户视图中缺少 K 的映射，用户态翻译无法沿这份页表得到 K 的物理页。入口仍需保留少量映射，进程之间的间接分支预测等状态也各有自己的处理规则。要判断别的机制，需重新确定它所使用的状态和边界。</p><details class="details custom-block"><summary>练习：用户页的映射更新了</summary><p>内核把用户页 U 原先指向的 <code>frame-u</code> 更换成 <code>frame-new</code>。此前用户 PCID 已缓存旧翻译，内核视图的用户部分也曾查到这个页。为什么更新下级页表项一次仍然不够？再回到用户态时，处理器应从哪个物理页取指？</p><p>下级页表项是共用的，改动一次即可让两个视图的下次遍历看到新页号。已有的 TLB 条目各自可能保留旧翻译，仍需按相关视图与处理器的失效规则处理。返回用户态且相关旧翻译已经失效后，重新翻译 U 才会得到 <code>frame-new</code>。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://docs.kernel.org/6.12/arch/x86/pti.html" target="_blank" rel="noreferrer">Linux v6.12 的 x86 页表隔离文档，两套页表及 PCID 处理</a></li><li><a href="https://github.com/torvalds/linux/blob/v6.12/arch/x86/entry/entry_64.S#L87" target="_blank" rel="noreferrer">Linux v6.12 的 64 位系统调用入口与快速返回代码</a></li><li><a href="https://github.com/torvalds/linux/blob/v6.12/arch/x86/entry/calling.h#L163" target="_blank" rel="noreferrer">Linux v6.12 的 CR3 切换宏</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel 软件开发者手册，SYSCALL、SYSRET、分页与 PCID</a></li><li><a href="https://commons.wikimedia.org/wiki/File:Kernel_page-table_isolation.svg" target="_blank" rel="noreferrer">Phoenix7777 绘制、Wdwd 修整的页表隔离原图</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0 许可</a> · 本文使用原图的 PNG 版本，正文以灰度显示，配图沿用同一许可。</li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-04e-meltdown.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>Meltdown 中的越权加载如何影响后续指令</strong></span></a></p><p><a href="./microarch-04c-variants.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>Spectre 变体中的分支与访存推测</strong></span></a></p></nav>`,29)]))}const m=a(o,[["render",t]]);export{b as __pageData,m as default};
